from pathlib import Path
import json,hashlib,re,unicodedata,collections
ROOT=Path('/dev/shm/komorebi_core_monograph_fbc994080222')
OUT=ROOT/'editorial/book_revision'
source=json.loads((OUT/'glossary_source_index.json').read_text())
terms=[]
def add(term,definition,see,cid,page,section,anchor):
    terms.append({'term':term,'definition':definition,'see_also':see,'references':[{'component_id':cid+'_traditional','local_page':page,'section':section,'anchor_quote':anchor}]})
add('Automorphic Hecke datum', 'A Hecke algebra with a finite automorphic module or perfect complex, declared unramified Hecke polynomials, and a characteristic zero locus where classicality and an attached Galois representation are supplied. These realization inputs are part of the datum.', ['Hecke packet','Residual automorphic occupancy'], 'XII',24,'Definition 9.1','Definition 9.1 (Automorphic Hecke datum)')
add('Block diagonal plus low rank operator', 'An operator represented as a block diagonal part plus one thin factor times the adjoint of another. This separates independent packet work from a coupling term of rank at most the factor width. The abbreviation is BDLR.', ['Packet operator representation','Output contract'], 'VIII',17,'Definition 3.3','Definition 3.3 (Block diagonal plus low rank operator)')
add('Bridge datum', 'In the restricted Galois to type comparison, supplied symplectic identification of two envelopes, compatible stabilizer action, and a common central character. At the prime two, compatible quadratic refinements and a lift to the central extensions are also required.', ['Symplectic envelope','Quadratic refinement'], 'XI',23,'Definition 11.1','Definition 11.1 (Bridge datum)')
add('Clifford cocycle class', 'The cohomology class of the scalar factors by which multiplication of projective multiplicity operators differs from the group law. In the one break setting, its commutator pairing determines the associated symplectic envelope.', ['Symplectic envelope','Bridge datum'], 'XI',21,'Definition 9.3','Definition 9.3 (Clifford cocycle class)')
add('Common arithmetic spine', 'Algebraic Frobenius characteristic polynomials, coefficient-prime independent weight and determinant data, and prescribed ramified local labels that companion objects must share. Specifying the spine imposes compatibility conditions. It does not ensure that the corresponding residual fibers are occupied.', ['Residual root','Residual forest','Automorphic Hecke datum'], 'X',22,'Definition 8.1','Definition 8.1 (Common arithmetic spine)')
add('Compatibility', 'Agreement of specified constructions along two routes. For fine and coarse nonlinear models, applying the fine map and then coarsening must equal coarsening first and applying the coarse map. Arithmetic compatibility uses the separately declared common data.', ['Refinement defect','Common arithmetic spine'], 'III',47,'Definition 20.1','The two models are exactly compatible when')
add('Complete multiplicative filtration', 'A decreasing filtration by two-sided ideals whose products add filtration depths, whose intersection is zero, and whose compatible quotient system recovers the algebra. Positive transfer weights then control convergent expansions in the filtration topology.', ['Weighted transfer series','Lift tree'], 'II',17,'Definition 5.1','Definition 5.1 (Complete multiplicative filtration)')
add('Complete packet pruning', 'A set of nodes in a finite refinement tree meeting every root-to-terminal path exactly once, with no selected node above another. Parent projectors split into child projectors, so the selected packets still sum to the identity.', ['Refinement','Packet system'], 'V',29,'Definition 11.1','Definition 11.1 (Complete packet pruning)')
add('Conditional expectation projector', 'For a fixed finite probability space and partition, the operator replacing a function by its probability-weighted mean on each partition block. It is an orthogonal projector in the corresponding weighted Hilbert space. Nested partitions yield compatible projections.', ['Projector','Packet system'], 'VI',17,'Section 6','Conditional expectation is a projector in a weighted Hilbert space')
add('Congruential Euler coefficients', 'Coefficients defined by the reciprocal of an exponential section with width N and address j. The original degree-indexed coefficients and normalized packet coefficients differ by the factor j!. Both the normalization and the distinction between degree and row matter in congruences.', ['Packet row','Hurwitz integral series','p-adic precision'], 'IX',17,'Definition 3.1','Definition 3.1 (Congruential Euler coefficients)')
add('Connection', 'A chosen family of invertible maps between chart coordinates. The minimal connection is normalized at each chart. The stronger reversible connection also inverts transport on reversed edges. Neither definition alone imposes the cocycle law or identifies the connection with canonical coordinate transport.', ['Flatness of a connection','Gauge change','Holonomy'], 'III',14,'Definition 5.1','Definition 5.1 (Noncanonical connection normalized at each chart)')
terms[-1]['references'].append({'component_id':'III_traditional','local_page':16,'section':'Definition 5.5','anchor_quote':'Definition 5.5 (Normalized reversible connection)'})
add('Cyclic vector', 'A single vector whose orbit under the declared unital algebra generates the whole module by finite linear combinations. A nonzero module has seed rank one precisely when it has such a vector. Cyclicity is always relative to the acting algebra.', ['Seed','Seed rank','Generated hull'], 'I',17,'Proposition 4.2','Proposition 4.2 (Cyclic characterization)')
add('Derived support', 'For a perfect complex over a commutative ring, the prime ideals at which derived tensor product with the residue field is nonzero. This support detects the complex after specialization, rather than relying on one selected cohomology module.', ['Module support','Ordinary patching datum'], 'XII',17,'Definition 6.14','Definition 6.14 (Derived support)')
add('Exact lumpability', 'Compatibility between a fine Markov transition and a coarse transition under a declared aggregation map. The one-step intertwining identity makes fine evolution followed by aggregation agree with coarse evolution at every nonnegative integer time.', ['Compatibility','Refinement defect','Transfer semigroup'], 'VI',16,'Theorem 5.1','Theorem 5.1 (Exact lumpability)')
add('Feshbach reduction', 'Elimination of hidden packets through their resolvent, producing an effective operator on the retained space. The correction records excursions through hidden packets. The exact resolvent identity requires the stated inverses and generally differs from bare compression.', ['Transfer block','Memory kernel'], 'VII',30,'Theorem I.9.1','Theorem I.9.1 (Exact Feshbach resolvent)')
add('Flatness of a connection', 'The cocycle condition: transport through any intermediate chart equals the declared direct transport. In the reversible pair setting, flatness is equivalent to trivial triangle holonomy. Flatness alone does not say that the connection is already canonically calibrated.', ['Connection','Holonomy','Gauge change'], 'III',16,'Definition 5.6','Definition 5.6 (Calibration and flatness)')
add('Forward difference', 'The difference between a sequence value after a declared step and its original value. Iterating this operation gives higher differences. In the Euler packet results the step acts on packet rows, so ordinary-degree displacement must be converted using the packet width.', ['Packet row','Congruential Euler coefficients','p-adic precision'], 'IX',18,'Definition 3.4','Definition 3.4 (Differences and valuation conventions)')
add('Gauge change', 'A change of coordinate representative at each chart by an automorphism. It acts on a connection by conjugating the source and target representatives separately. Cocycle defects transform covariantly, while loop holonomy is conjugated at its base.', ['Connection','Flatness of a connection','Holonomy'], 'III',18,'Definition 6.1','Definition 6.1 (Gauge change)')
add('Generated hull', 'All finite sums of seed vectors acted on by elements of the declared algebra. In a topological realization, the topological hull is its closure. Algebraic generation and dense generation are distinct because closure may add limits with no finite addressed expression.', ['Seed','Seed rank','Realization'], 'I',12,'Definition 2.7','Definition 2.7 (Generated hull)')
add('Global deformation datum', 'A residual representation, local deformation rings and represented local-condition quotients, a global deformation ring, and compatible maps imposing those local conditions globally. Existence and representability of these objects require their own hypotheses. The datum does not establish automorphic occupancy.', ['Residual root','Residual automorphic occupancy','Ordinary patching datum'], 'XII',6,'Definition 2.1','Definition 2.1 (Global deformation datum)')
add('Hecke packet', 'The part of a finite Hecke module selected by a central idempotent of its finite dimensional commutative Hecke algebra. It is nonzero precisely at an occupied maximal ideal. Over an algebraically closed field it is a simultaneous generalized eigenspace, retaining nilpotent data.', ['Module support','Automorphic Hecke datum','Stable core'], 'XII',20,'Theorem 8.2','Theorem 8.2 (Canonical Hecke packet decomposition)')
add('Holonomy', 'The composite transport around a loop for a chosen connection, based at its starting chart. Triangle holonomy measures the failure of a reversible pair connection to satisfy its cocycle law. It is not an invariant of an unspecified change of coordinates.', ['Connection','Flatness of a connection','Gauge change'], 'III',17,'Definition 5.9','Definition 5.9 (Triangle holonomy)')
add('Hurwitz integral series', 'An exponential generating series whose factorial-basis coefficients are p-adic integers. Products and differentiation preserve this lattice. A series in it with unit constant coefficient has its reciprocal in the same lattice, supporting the reciprocal-transfer congruence arguments.', ['Congruential Euler coefficients','p-adic precision'], 'IX',34,'Definition 4.1','Definition 4.1 (Hurwitz integral series)')
add('Kraus channel', 'A finite sum of maps sending a matrix to K times that matrix times the adjoint of K, with the adjoint products summing to the identity. This normalization makes the resulting completely positive map trace preserving.', ['Quantum seed system','Packet system'], 'VII',26,'Classical Input I.7.2','Classical Input I.7.2 (Finite Kraus channel)')
add('Krylov space', 'The span of a vector and its successive images under one operator, through a specified finite order. This records how repeated application enlarges the generated space. Packet decompositions interact with it under the invariance hypotheses stated in the relevant result.', ['Cyclic vector','Generated hull','Packet operator representation'], 'VIII',30,'Definition 7.1','Definition 7.1 (Krylov space)')
add('Lift tree', 'A rooted tree of approximation classes at increasing filtration depths. A child reduces to its parent and satisfies the next depth condition. Nonempty levels and finite branching provide a compatible branch. Completeness, separatedness and continuity are further needed to recover an exact solution.', ['Complete multiplicative filtration','Obstruction class','Residual forest'], 'III',59,'Definition 23.5 and Theorem 23.6','Definition 23.5 (Lift tree)')
add('Memory kernel', 'The time-dependent operator describing how eliminated packets return influence to retained packets. In the finite linear system it is a transfer into the hidden block, hidden evolution, and transfer back. Its Laplace transform is the corresponding self-energy under the stated spectral condition.', ['Feshbach reduction','Transfer semigroup','Transfer block'], 'VI',38,'Section 13.1 and Theorem 13.2','Theorem 13.2 (Memory/self-energy correspondence)')
add('Module support', 'The prime ideals of a commutative ring at which localization of the module is nonzero. Full support means every prime is occupied in this algebraic sense. It does not by itself provide a classical automorphic realization.', ['Near faithfulness','Derived support','Hecke packet'], 'XII',14,'Definition 6.1','Definition 6.1 (Support and near faithfulness)')
add('Monodromy packet chain', 'A finite sequence of packet spaces joined by a nilpotent operator that moves each packet down one level. A compatible Frobenius operator scales this transfer by the declared residue-field factor. Its powers are sums of paths along the chain.', ['Transfer block','Transfer graph'], 'XI',8,'Definition 2.2 and Proposition 2.3','A monodromy packet chain is a nilpotent operator')
add('Near faithfulness', 'For a finite module over a Noetherian ring, nilpotence of its annihilator ideal. This is equivalent to full module support. If the ring is reduced it is also equivalent to faithfulness. The finiteness and ring hypotheses are part of the equivalence.', ['Module support','Ordinary patching datum'], 'XII',15,'Theorem 6.7','Theorem 6.7 (Near faithfulness is full support)')
add('Obstruction class', 'The class of a defect in the cokernel of a declared linear correction map. It vanishes exactly when that linear correction can remove the defect. The quotient, not the size of the defect, determines this solvability question.', ['Refinement defect','Obstruction packet','Lift tree'], 'III',49,'Definition 21.1 and Theorem 21.2','Definition 21.1 (Linear correction datum)')
add('Obstruction packet', 'A named packet with a certificate that the residual of one specified candidate is nonzero. It rules out that candidate under the declared solution condition. It neither constructs a solution nor proves that every possible candidate is obstructed.', ['Obstruction class','Residual','Packet'], 'III',20,'Definition 7.1 and Theorem 7.2','An obstruction packet for')
add('Ordinary patching datum', 'A Noetherian patched ring, an ideal, and a finite patched module, together with identifications of the finite-level ring and module as their quotients. Full patched support descends under these hypotheses. Automorphy requires additional arithmetic data.', ['Module support','Near faithfulness','Global deformation datum'], 'XII',15,'Definition 6.10','Definition 6.10 (Ordinary patching datum)')
add('Output contract', 'The mathematical object an algorithm is required to return, such as an explicit vector, matrix, factors, or an implicit operator with an application rule. Costs are comparable only after the represented object and required output are fixed.', ['Packet operator representation','Block diagonal plus low rank operator'], 'VIII',15,'Definition 2.7','Definition 2.7 (Output contract)')
add('Packet', 'In the linear theory, a component selected by a declared projector, usually identified with its range and index. Analytic, signal and arithmetic realizations attach their own additional structure. The meaning of a packet is therefore read with its specified system.', ['Packet system','Projector','Transfer block'], 'I',28,'Definition 7.1','Definition 7.1 (Finite packet system)')
add('Packet analysis and synthesis', 'Analysis sends an object to its tuple of projected packet components. Synthesis adds those components in the ambient space. For a finite complete packet system the maps are inverse isomorphisms. Infinite versions require a specified convergence mode and corresponding bounds.', ['Packet system','Packet support','Refinement'], 'I',29,'Definition 7.4 and Theorem 7.5','Definition 7.4 (Packet analysis and synthesis)')
add('Packet jet', 'A higher derivative restricted to specified input packet spaces and projected to a specified output packet. Summing over all addresses reconstructs the derivative exactly. The analytic statements require the stated bounded projectors and continuous Fréchet differentiability.', ['Packet','Transfer block'], 'III',37,'Definition 17.1','Definition 17.1 (Packet jet)')
add('Packet operator representation', 'A finite packet layout, a declared set of active input-output addresses, and a linear block at each address. Evaluation extends each local block to the ambient direct sum and adds the blocks. Thus the representation has an explicit operator meaning.', ['Transfer block','Output contract','Block diagonal plus low rank operator'], 'VIII',13,'Definition 2.2','Definition 2.2 (Packet operator representation)')
add('Packet row', 'The index n within a fixed coefficient packet of width N. For the reciprocal Euler family, row n corresponds to ordinary degree Nn. A step of u rows therefore changes ordinary degree by Nu, a distinction needed when stating periods and difference estimates.', ['Congruential Euler coefficients','Forward difference'], 'IX',34,'Section 4, equations (4.1)-(4.2)','A mixed difference')
add('Packet support', 'The set of packet indices on which an object has a nonzero projected component. A packet-pure vector has at most one such index, including the zero vector. This is different from module support in a prime spectrum.', ['Packet','Seed rank','Module support'], 'I',29,'Definition 7.2','Definition 7.2 (Packet support and packet pure vectors)')
add('Packet system', 'A finite family of idempotent operators that annihilate one another and sum to the identity, giving an exact direct-sum decomposition into their ranges. Orthogonality is an additional condition when stated. Some chapters remove zero packet spaces by convention.', ['Projector','Packet analysis and synthesis','Refinement'], 'I',28,'Definition 7.1','No orthogonality is assumed unless stated')
add('Perfect reconstruction', 'Recovery of every input by composing a filter bank with its synthesis bank, with any permitted gain and delay declared explicitly. The criterion is an identity of Laurent-polynomial matrices. A delay in decimated channel indices differs from a delay in original sample addresses.', ['Polyphase channel','Packet analysis and synthesis'], 'V',16,'Theorem 4.1','Theorem 4.1 (Perfect-reconstruction criterion)')
add('Polyphase channel', 'The decimated sequence obtained by retaining one residue class of sample addresses and reindexing it on a coarse lattice. Its masked counterpart remains on the original lattice with other samples set to zero. Interleaving reconstructs the original sequence from all channels.', ['Residue selector','Perfect reconstruction'], 'V',11,'Section 2 and Theorem 2.1','The corresponding decimated channel is')
add('Projector', 'An idempotent linear operator: applying it twice has the same effect as applying it once. Its range is the selected component. The general packet calculus does not require an orthogonal projector, although Hilbert space and quantum results may impose self-adjointness.', ['Packet system','Packet'], 'I',28,'Definition 7.1','Definition 7.1 (Finite packet system)')
add('Quadratic refinement', 'Over the field with two elements, a quadratic function whose polar difference recovers a specified symplectic form. The alternating form alone does not determine the refinement. This additional datum controls dyadic phase information in the arithmetic packet constructions.', ['Symplectic envelope','Bridge datum'], 'XI',26,'Definition 13.1','Definition 13.1 (Quadratic refinement)')
add('Quantum seed system', 'A finite Hilbert space with a nonzero seed, a declared operator grammar, constraints, packet systems at refinement levels, and the relevant dynamical and topological data. Its generated span is algebraic. Reachability by a restricted physical gate set is a separate question.', ['Seed','Cyclic vector','Kraus channel'], 'VII',13,'Definition I.1.1','Definition I.1.1 (Finite quantum seed system)')
add('Realization', 'An assignment of spaces and linear maps to a typed operator grammar that satisfies its relations. More generally, a domain realization interprets specified abstract seed constructions in a chosen mathematical setting. Which operations and universal properties survive must be declared.', ['Typed operator grammar','Realization functor','Seed'], 'I',10,'Definition 2.1','that annihilate every relation in')
add('Realization functor', 'A functor from abstract seed systems to a declared domain category, equipped with a preservation profile. The profile states which identities or universal properties it preserves, such as sums, compositions, packet idempotents, quotients, or completions.', ['Realization','Typed operator grammar'], 'I',53,'Definition 11.1','Definition 11.1 (Realization functor and preservation profile)')
add('Reduced denominator', 'The one-variable entire function obtained from the signed exponential denominator by using a coordinate w equal to the Nth power of z. A root in the reduced coordinate records a root-of-unity orbit in the original variable, with multiplicities retained.', ['Residue selector','Transfer tangent','Zero power sum'], 'IV',13,'Definition 5.7','Definition 5.7. Define the reduced denominator')
add('Refinement', 'A finer packet system whose projectors sum to each coarse projector according to a surjective parent map. Fine packet ranges lie in their parent ranges. Exact refinement regroups complete component vectors and need not discard information.', ['Packet system','Packet analysis and synthesis','Complete packet pruning'], 'II',7,'Definition 3.2','Definition 3.2 (Refinement)')
add('Refinement defect', 'The difference between applying a fine model and then coarsening, and coarsening first and applying the coarse model. Its vanishing expresses exact compatibility. A correction map must be specified before this vector defines a corresponding obstruction class.', ['Compatibility','Obstruction class','Exact lumpability'], 'III',47,'Definition 20.1','Definition 20.1 (Nonlinear refinement defect)')
add('Residual', 'In the candidate-certificate language, the value of a declared test at a candidate and packet. A solution makes every such value zero. This use of residual as a test value is distinct from reduction to a residue field in arithmetic deformation problems.', ['Obstruction packet','Residual root'], 'III',19,'Section 7.1 and Definition 7.1','be a residual function')
add('Residual automorphic occupancy', 'Existence of a nonzero localized automorphic or cohomological Hecke carrier realizing a specified residual representation and local conditions. It is an input at residual depth. Positive-depth deformations over another residual root do not supply it.', ['Residual root','Automorphic Hecke datum','Global deformation datum'], 'XII',6,'Definition 2.4','Definition 2.4 (Residual automorphic occupancy)')
add('Residual forest', 'The family of formal deformation problems above the admissible residual roots. Higher-depth objects are related by reduction, so each root has its own lifting branches. Declaring the forest does not establish that every intended branch or characteristic zero realization exists.', ['Residual root','Lift tree','Common arithmetic spine'], 'X',6,'Definition 1.1','formal deformation problems above them form the residual forest')
add('Residual root', 'An object over the residue field, fixed as the reduction of all objects in its residual fiber. Positive-depth corrections preserve this root. A universal arithmetic seed system therefore records all admissible roots rather than assuming one root represents every residual class.', ['Residual forest','Residual automorphic occupancy','Visibility weight'], 'X',6,'Definition 1.1','The family of all nonempty fibers is the residual special fiber')
add('Residue selector', 'The coefficient projector retaining exactly the exponents in one congruence class modulo a positive integer. It is defined directly by a coefficient mask and needs no division. A realization as a roots-of-unity average requires additional orthogonality hypotheses.', ['Roots of unity filter','Polyphase channel','Refinement'], 'II',13,'Definition 4.1','Definition 4.1 (Residue selector)')
add('Roots of unity filter', 'A finite character average realizing a residue selector when the required Fourier orthogonality certificate holds. Over a field with a primitive root, the usual normalization divides by the width. Over more general coefficient rings, the coefficient selector remains meaningful even when that average is unavailable.', ['Residue selector','Separation weight'], 'II',14,'Theorem 4.3','Theorem 4.3 (Root-of-unity realization)')
add('Seed', 'A distinguished starting element acted on by a declared operator algebra or grammar. A seed family generates its hull through addressed operator expressions and finite sums, with closure added only in a specified topological regime. The acting algebra is fixed independently of the target.', ['Generated hull','Seed rank','Typed operator grammar'], 'I',12,'Definition 2.6','Definition 2.6 (Linear seed system)')
add('Seed rank', 'The least size of a family generating a module under the declared acting algebra. In the topological version, generation is replaced by dense generation. The zero module has rank zero. Changing the acting algebra can change the seed rank of the same underlying space.', ['Seed','Generated hull','Cyclic vector'], 'I',17,'Definition 4.1','Definition 4.1 (Seed rank)')
add('Seed zeta function', 'The formal power series whose coefficient at each positive depth counts the finite objects above one residual root at that depth. Smooth and weighted charts yield explicit formulas under their stated assumptions. It records branching counts, not just the existence of a lift.', ['Residual forest','Visibility weight'], 'X',16,'Definition 6.1','Definition 6.1 (Seed zeta function)')
add('Separation weight', 'The least exponent of a uniformizer that makes a rational projector preserve a specified integral lattice, provided such an exponent exists. It records the precision needed to clear that projector on that lattice and is distinct from the visibility depth of two coordinates.', ['Projector','Visibility weight','Roots of unity filter'], 'II',30,'Definition 7.6','Definition 7.6 (Separation weight)')
add('Singular packet', 'In the signal chapter, a step or truncated-power component recording a value jump or a derivative jump at a declared breakpoint. Removing the trace jumps leaves the regular remainder covered by the stated Sobolev assumptions. Representation alone does not solve data-driven recovery.', ['Packet','Perfect reconstruction'], 'V',66,'Section E7','The simplest singular packets are steps')
add('Stable core', 'At one level of an inverse system of finite dimensional spaces, the intersection of the images of every later level. It retains vectors that remain liftable arbitrarily far. Nonzero stable cores at every level provide compatible nonzero inverse-limit vectors, unlike mere nonvanishing of unrelated levels.', ['Hecke packet','Lift tree'], 'XII',23,'Definition 8.9 and Theorem 8.11','The stable core at level')
add('Symplectic envelope', 'For a one break Clifford datum, the quotient of the finite elementary abelian group by the radical of its intrinsic commutator pairing. This removes the degenerate directions of that pairing. Comparison with a type-side envelope requires the additional bridge data.', ['Clifford cocycle class','Bridge datum','Quadratic refinement'], 'XI',21,'Definition 9.5','Definition 9.5 (One break symplectic envelope)')
add('Transfer block', 'The part of an operator carrying one input packet to one output packet: first select the input, apply the operator, and select the output. Summing all blocks reconstructs the operator for a finite complete packet system.', ['Packet system','Transfer graph','Packet operator representation'], 'I',35,'Definition 8.1','Definition 8.1 (Transfer block)')
add('Transfer graph', 'A directed graph on packet indices, with an edge where a declared algebra generator has a nonzero transfer block. Reachability limits where generated operators may have nonzero blocks. An allowed path does not prevent cancellation or guarantee a nonzero transfer.', ['Transfer block','Seed rank','Packet operator representation'], 'I',42,'Definition 9.1','Definition 9.1 (Transfer graph of a family generating the algebra)')
add('Transfer semigroup', 'A family of evolution operators whose composition adds time and whose value at zero is the identity. In the finite setting it is generated by a matrix exponential. The sign convention differs between generators of evolution and nonnegative diffusion operators.', ['Memory kernel','Exact lumpability'], 'VI',9,'Definition 1.1 and Theorem 1.2','Definition 1.1 (Transfer-semigroup seed system)')
add('Transfer tangent', 'The negative logarithmic derivative of the signed exponential denominator in the cyclic analytic family. It is also the logarithmic derivative of the first reciprocal power. Its expansion connects reciprocal coefficient recurrences to logarithmic coefficients and reduced zero power sums.', ['Reduced denominator','Zero power sum'], 'IV',22,'Definition 8.1','Definition 8.1. Define the transfer tangent')
add('Typed operator grammar', 'A quiver of permitted source and target types together with linear relations among paths having the same endpoints. Its quotient path algebra encodes composition and relations. A realization assigns spaces to vertices and maps to arrows satisfying those relations.', ['Realization','Seed','Transfer graph'], 'I',10,'Definition 2.1','Definition 2.1 (Typed operator grammar)')
add('Visibility weight', 'The first precision depth at which two distinct integral packet coordinates have different reductions, when such a depth exists. At the prime two, signs may share a residual reduction yet separate at a later depth. This weight measures separation of coordinates, not a projector denominator.', ['Separation weight','Residual root','Seed zeta function'], 'X',14,'Definition 5.1','Definition 5.1 (Visibility weight)')
add('Weighted transfer series', 'A generating series for walks in a finite directed multigraph with positive integer edge weights and scalar multiplicities. It sums multiplicity products and endpoint weights at each total weight, including the empty walk. The positive weights make each coefficient well defined.', ['Transfer graph','Complete multiplicative filtration'], 'II',24,'Definition 6.1','Definition 6.1 (Weighted transfer series)')
add('Zero power sum', 'A sum of inverse powers of the reduced zeros of the cyclic analytic denominator, counted with multiplicity. For section order N at least two, these sums converge absolutely and agree with the normalized logarithmic coefficients through the genus zero product.', ['Reduced denominator','Transfer tangent'], 'IV',40,'Definition 12.5 and Theorem 12.6','Definition 12.5. For')
add('p-adic precision', 'A lower bound on the p-adic valuation in the declared integral coefficient ring. The Euler congruence statements assign infinite valuation to zero. Divisibility in the field alone does not express precision, and special finite conventions for a zero step are stated separately.', ['Congruential Euler coefficients','Forward difference','Hurwitz integral series'], 'IX',18,'Definition 3.4','For p-adic congruences, divisibility is interpreted')

def norm(s):
    return ''.join(c for c in unicodedata.normalize('NFKC',s).casefold() if c.isalnum())
terms.sort(key=lambda t:t['term'].casefold())
names={t['term'] for t in terms};assert len(names)==len(terms)
checks=[]
for t in terms:
    assert all(s in names and s!=t['term'] for s in t['see_also']), t['term']
    for ref in t['references']:
        p=source[ref['component_id']]['pages'][ref['local_page']-1]
        assert norm(ref['anchor_quote']) in norm(p),(t['term'],ref)
        matches=[n+1 for n,text in enumerate(source[ref['component_id']]['pages']) if norm(ref['anchor_quote']) in norm(text)]
        ref['anchor_matching_local_pages']=matches
        checks.append({'term':t['term'],'component_id':ref['component_id'],'local_page':ref['local_page'],'anchor_found':True,'anchor_matching_pages':matches})
rows=[]
for cid,x in source.items():
 p=ROOT/x['path']
 with p.open('rb') as f:h=hashlib.file_digest(f,'sha256').hexdigest()
 rows.append({'component_id':cid,'path':x['path'],'sha256':h,'pages':len(x['pages'])})
data={'schema':'realization-calculus.glossary/1','title':'Glossary','introduction':'This glossary follows the terminology of the twelve chapters. Each entry points to the treatment that fixes its meaning. Local hypotheses and notation remain those of the cited result. Shared words, including packet, support and residual, should be read in that setting.','terms':terms,'source_basis':rows,'validation':{'term_count':len(terms),'reference_count':len(checks),'all_anchors_verified':True,'all_see_also_targets_exist':True,'chapters_covered':list(source),'scope':'Definitions checked against the cited mathematical-text pages. This is a terminology and reference review, not an independent proof audit.','anchor_match_normalization':'Unicode NFKC, casefold, alphanumeric characters only; explicit local pages disambiguate repeated anchors.'}}
(OUT/'glossary.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
(OUT/'glossary_anchor_validation.json').write_text(json.dumps(checks,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(data['validation'],indent=2))
print('Definition words',sum(len(t['definition'].split()) for t in terms))
print('Repeated anchors',[(c['term'],c['anchor_matching_pages']) for c in checks if len(c['anchor_matching_pages'])!=1])
